_CODE = re.compile(r"^([A-Za-z]+)(\d+)$")


def book_max() -> int:
    return max(row["seq"] for row in NUMBERS)


def sequence_of(code: str) -> int | None:
    match = _CODE.fullmatch((code or "").strip())
    return int(match.group(2)) if match else None


def next_number(existing: list[str]) -> int:
    highest = book_max()
    for code in existing:
        found = sequence_of(code)
        if found is not None:
            highest = max(highest, found)
    return highest + 1


def next_code(tag: str, existing: list[str]) -> str:
    return f"{tag.strip().upper()}{next_number(existing)}"


def tag_brand(tag: str) -> str:
    key = tag.strip().upper()
    for row in TAGS:
        if row["tag"] == key:
            return row["brand"]
    return ""
